def main() -> None:
    # Initialize Composio with OpenAI provider
    composio = Composio(provider=OpenAIProvider())

    # Create a session for the test user
    session = composio.create_session(user_id="zealt-user01")

    # Apply schema modifier to hide and hardcode the org argument
    schema_modifier = SchemaModifier(
        {
            Action.GITHUB_GET_ORGANIZATION: {
                "org": {"value": "ComposioHQ", "hide": True}
            }
        }
    )

    # Initialize Workbench
    workbench = Workbench()

    # Collect the modified GitHub tool and the Workbench tool
    tools = composio.get_tools(
        apps=[App.GITHUB],
        schema_modifier=schema_modifier,
        session_id=session.id,
    )

